CREATE TABLE inventory_quota_versions (
  id VARCHAR(64) PRIMARY KEY,
  version_code VARCHAR(64) NOT NULL,
  effective_date DATE NOT NULL,
  status VARCHAR(24) NOT NULL DEFAULT 'ACTIVE',
  created_by VARCHAR(120) NOT NULL,
  confirmed_by VARCHAR(120) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  UNIQUE KEY uk_inventory_quota_version_code (version_code),
  UNIQUE KEY uk_inventory_quota_effective_date (effective_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE inventory_quota_rules (
  id VARCHAR(96) PRIMARY KEY,
  version_id VARCHAR(64) NOT NULL,
  department_key VARCHAR(64) NOT NULL,
  department_name VARCHAR(120) NOT NULL,
  source_row INT NOT NULL,
  service_group VARCHAR(160) NOT NULL,
  care_type VARCHAR(24) NOT NULL,
  material_name VARCHAR(255) NOT NULL,
  unit VARCHAR(64) NOT NULL,
  standard_quantity DECIMAL(18,6) NULL,
  fixed_adjustment DECIMAL(18,6) NOT NULL DEFAULT 0,
  measurement_scope VARCHAR(24) NOT NULL,
  enabled TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  CONSTRAINT fk_inventory_quota_rule_version FOREIGN KEY (version_id) REFERENCES inventory_quota_versions(id),
  UNIQUE KEY uk_inventory_quota_rule_source (version_id, department_key, source_row),
  INDEX idx_inventory_quota_rule_department (version_id, department_key, enabled)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE inventory_special_material_rules (
  id VARCHAR(64) PRIMARY KEY,
  department_key VARCHAR(64) NOT NULL,
  material_name VARCHAR(255) NOT NULL,
  unit VARCHAR(64) NOT NULL,
  enabled TINYINT(1) NOT NULL DEFAULT 1,
  admin_note VARCHAR(1000) NOT NULL DEFAULT '',
  updated_by VARCHAR(120) NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  UNIQUE KEY uk_inventory_special_material (department_key, material_name, unit),
  INDEX idx_inventory_special_material_department (department_key, enabled)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE inventory_quota_review_records (
  id VARCHAR(64) PRIMARY KEY,
  business_date DATE NOT NULL,
  department_key VARCHAR(64) NOT NULL,
  line_key VARCHAR(128) NOT NULL,
  material_name VARCHAR(255) NOT NULL,
  unit VARCHAR(64) NOT NULL,
  review_status VARCHAR(24) NOT NULL DEFAULT 'PENDING',
  review_note VARCHAR(2000) NOT NULL DEFAULT '',
  reviewer_username VARCHAR(120) NOT NULL,
  reviewer_name VARCHAR(120) NOT NULL,
  reviewed_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  UNIQUE KEY uk_inventory_quota_review_target (business_date, department_key, line_key),
  INDEX idx_inventory_quota_review_date (business_date, department_key, review_status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

VALUES ('quota-v1', 'quota-v1', CURRENT_DATE, 'ACTIVE', 'system-v32', 'system-v32');
